  const now = new Date();
  const handover = await requireActionableHandover(actor, orgId, now);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (incoming.role !== "owner") {
    await changeRole(actor, incoming, "owner");
  }

  const org = await orgRepo.setOrgOwner(orgId, actor.userId);

  const outgoing = await memberRepo.findMember(orgId, handover.fromUserId);
  if (outgoing && outgoing.id !== incoming.id && outgoing.role === "owner") {
    await changeRole(actor, outgoing, "admin");
  }

  await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(now),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: actor.userId,
  });

