  return now.getTime() >= Date.parse(handover.expiresAt);
}

/**
 * Loads the org and refuses anyone but its recorded owner. A second member
 * holding the owner role is refused just like any other non-owner.
 */
async function requireRecordedOwner(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  if (org.ownerId !== actor.userId) {
    const decision = explain(actor, "org:delete", orgResource(orgId));
    throw new PermissionDeniedError("org:delete", {
      ...decision,
      allowed: false,
      reason: decision.allowed ? "denied_by_role" : decision.reason,
    });
  }

  return org;
}

