async function requireActionableHandover(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending, now)) throw new OwnershipHandoverError("expired");
  return pending;
}

/** A handover-driven role change, announced exactly as a manual one is. */
async function changeRole(
  actor: Actor,
  member: Member,
  role: Member["role"],
): Promise<Member> {
  const updated = await memberRepo.updateMemberRole(orgId(member), member.id, role);
  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });
  return updated;
}

function orgId(member: Member): OrgId {
  return member.orgId;
}
