import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError, toAppError } from "@/lib/errors";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgService from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import * as billing from "@/server/services/billing-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerActivityListeners(); });
afterAll(() => cleanup());

describe("handover", () => {
  it("flows", async () => {
    const t = await createTenant("ho", "growth");
    const events: unknown[] = [];
    subscribe("member.role_changed", (p) => { events.push(p); });
    subscribe("organization.ownership_transferred", (p) => { events.push(p); });
    await expect(orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner)).rejects.toMatchObject({ reason: "self" });
    const h = await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(Date.parse(h.expiresAt) - Date.parse(h.createdAt)).toBe(7 * 86400000);
    await expect(orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin)).rejects.toMatchObject({ reason: "pending_exists" });
    await expect(orgService.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    expect((await orgService.getPendingOwnershipHandover(t.actors.viewer, t.org.id))?.toUserId).toBe(t.userIds.member);
    const org = await orgService.acceptOwnershipHandover(t.actors.member, t.org.id);
    expect(org.ownerId).toBe(t.userIds.member);
    expect((await memberRepo.findMember(t.org.id, t.userIds.owner))?.role).toBe("admin");
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))?.role).toBe("owner");
    expect(events.length).toBe(3);
    const oldOwner = await memberService.resolveActor(t.userIds.owner, t.org.id);
    await expect(billing.changePlan(oldOwner!, { orgId: t.org.id, plan: "starter" } as never)).rejects.toThrow();
    const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
    console.log(JSON.stringify(acts.items.map((a) => [a.action, a.metadata])));
    expect(toAppError(new OwnershipHandoverError("expired")).code).toBe("conflict");
    await expect(orgService.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
  });
  it("expires and auto-cancels", async () => {
    const t = await createTenant("ho2", "growth");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));
    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    vi.setSystemTime(new Date("2026-01-08T00:00:00.000Z"));
    await expect(orgService.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    expect(await orgService.getPendingOwnershipHandover(t.actors.member, t.org.id)).toBeNull();
    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin);
    const adm = await memberRepo.findMember(t.org.id, t.userIds.admin);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: adm!.id });
    expect(await orgService.getPendingOwnershipHandover(t.actors.member, t.org.id)).toBeNull();
    vi.useRealTimers();
  });
});
